INSERT [dbo].[ProblemDetail] ([ProblemDetailId], [ProblemId], [LanguageName], [StarterCode], [HiddenCode], [GoldenSolution], [IsActive], [CreatedOn], [CreatedBy], [UpdatedOn], [UpdatedBy]) VALUES (1, 2, N'c', N'bool isValid(char* s) {
    // Write your code here
}', N'#include <stdio.h>
#include <stdbool.h>
#include <string.h>

bool isValid(char* s);

int main() {
    char s[10000];
    scanf("%s", s);
    printf("%s", isValid(s) ? "true" : "false");
    return 0;
}', N'#include <stdbool.h>
#include <string.h>

bool isValid(char* s) {
    char stack[10000];
    int top = -1;
    for (int i = 0; s[i]; i++) {
        char c = s[i];
        if (c == ''('' || c == ''{'' || c == ''['') stack[++top] = c;
        else if (top == -1) return false;
        else if ((c == '')'' && stack[top] != ''('') ||
                 (c == ''}'' && stack[top] != ''{'') ||
                 (c == '']'' && stack[top] != ''[''))
            return false;
        else top--;
    }
    return top == -1;
}', 1, CAST(N'2025-11-03T13:12:05.830' AS DateTime), 101, NULL, NULL)
GO
INSERT [dbo].[ProblemDetail] ([ProblemDetailId], [ProblemId], [LanguageName], [StarterCode], [HiddenCode], [GoldenSolution], [IsActive], [CreatedOn], [CreatedBy], [UpdatedOn], [UpdatedBy]) VALUES (2, 2, N'cpp', N'bool isValid(string s) {
    // Write your code here
}', N'#include <bits/stdc++.h>
using namespace std;

bool isValid(string s);

int main() {
    string s;
    cin >> s;
    cout << (isValid(s) ? "true" : "false");
}', N'#include <bits/stdc++.h>
using namespace std;

bool isValid(string s) {
    stack<char> st;
    unordered_map<char, char> mp = {{'')'',''(''},{'']'',''[''},{''}'',''{''}};
    for (char c : s) {
        if (mp.find(c) == mp.end()) st.push(c);
        else {
            if (st.empty() || st.top() != mp[c]) return false;
            st.pop();
        }
    }
    return st.empty();
}', 1, CAST(N'2025-11-03T13:12:05.840' AS DateTime), 101, NULL, NULL)
GO
INSERT [dbo].[ProblemDetail] ([ProblemDetailId], [ProblemId], [LanguageName], [StarterCode], [HiddenCode], [GoldenSolution], [IsActive], [CreatedOn], [CreatedBy], [UpdatedOn], [UpdatedBy]) VALUES (3, 2, N'Java', N'class Solution {
    public boolean isValid(String s) {
        // Write your code here
    }
}', N'import java.util.*;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        Solution sol = new Solution();
        System.out.print(sol.isValid(s));
    }
}', N'import java.util.*;

class Solution {
    public boolean isValid(String s) {
        Stack<Character> st = new Stack<>();
        Map<Character, Character> map = Map.of('')'', ''('', ''}'', ''{'', '']'', ''['');
        for (char c : s.toCharArray()) {
            if (!map.containsKey(c)) st.push(c);
            else if (st.isEmpty() || st.pop() != map.get(c)) return false;
        }
        return st.isEmpty();
    }
}', 1, CAST(N'2025-11-03T13:12:05.843' AS DateTime), 101, NULL, NULL)
GO
