INSERT [dbo].[ProblemDetail] ([ProblemDetailId], [ProblemId], [LanguageName], [StarterCode], [HiddenCode], [GoldenSolution], [IsActive], [CreatedOn], [CreatedBy], [UpdatedOn], [UpdatedBy]) VALUES (5, 2, N'C#', N'using System;
using System.Collections.Generic;

public class Solution {
    public bool IsValid(string s) {
        // Write your code here
    }
}', N'using System;

public class Program {
    public static void Main(string[] args) {
        string s = Console.ReadLine();
        Solution sol = new Solution();
        Console.WriteLine(sol.IsValid(s).ToString().ToLower());
    }
}', N'using System;
using System.Collections.Generic;

public class Solution {
    public bool IsValid(string s) {
        Stack<char> stack = new Stack<char>();
        Dictionary<char, char> map = new Dictionary<char, char> {
            {'')'', ''(''}, {'']'', ''[''}, {''}'', ''{''}
        };

        foreach (char c in s) {
            if (!map.ContainsKey(c))
                stack.Push(c);
            else if (stack.Count == 0 || stack.Pop() != map[c])
                return false;
        }
        return stack.Count == 0;
    }
}', 1, CAST(N'2025-11-03T13:12:05.850' AS DateTime), 101, NULL, NULL)
