INSERT [dbo].[ProblemDetail] ([ProblemDetailId], [ProblemId], [LanguageName], [StarterCode], [HiddenCode], [GoldenSolution], [IsActive], [CreatedOn], [CreatedBy], [UpdatedOn], [UpdatedBy]) VALUES (6, 2, N'JavaScript', N'function isValid(s) {
