INSERT [dbo].[UserSessionChat] ([UserSessionChatId], [UserProblemSessionId], [ChatMessage], [Correctness], [Completeness], [Clarity], [Alignment], [Readiness], [SentOn], [IsActive], [CreatedOn], [CreatedBy], [UpdatedOn], [UpdatedBy], [MessageType], [AiResponse], [AiReply], [AiExplaination], [IsAfterSubmit], [UserId]) VALUES (1, 33, N'I guess if it is opened and closed both available then it is valid ', CAST(0.80 AS Decimal(4, 2)), CAST(0.30 AS Decimal(4, 2)), CAST(0.70 AS Decimal(4, 2)), CAST(0.90 AS Decimal(4, 2)), CAST(0.70 AS Decimal(4, 2)), CAST(N'2025-09-23T20:22:17.077' AS DateTime), 1, CAST(N'2025-09-23T20:22:17.110' AS DateTime), 1, NULL, NULL, N'User', N'{"verbal_reply":"That\u0027s a great start! You\u0027ve identified the core idea. Now, how would you handle nested parentheses, like \u0022({[]})\u0022, and what data structure might be useful for keeping track of the opening parentheses?","scores":{"correctness":0.8,"completeness":0.3,"clarity":0.7,"alignment":0.9},"explaination_of_approach":"The user identifies that an opening parenthesis needs to be closed for validity."}', N'That''s a great start! You''ve identified the core idea. Now, how would you handle nested parentheses, like "({[]})", and what data structure might be useful for keeping track of the opening parentheses?', N'The user identifies that an opening parenthesis needs to be closed for validity.', 0, 0)
