INSERT [dbo].[UserSessionChat] ([UserSessionChatId], [UserProblemSessionId], [ChatMessage], [Correctness], [Completeness], [Clarity], [Alignment], [Readiness], [SentOn], [IsActive], [CreatedOn], [CreatedBy], [UpdatedOn], [UpdatedBy], [MessageType], [AiResponse], [AiReply], [AiExplaination], [IsAfterSubmit], [UserId]) VALUES (2, 33, N'data structure ? not sure about that... I guess I''m ediot', CAST(0.30 AS Decimal(4, 2)), CAST(0.20 AS Decimal(4, 2)), CAST(0.40 AS Decimal(4, 2)), CAST(0.70 AS Decimal(4, 2)), CAST(0.36 AS Decimal(4, 2)), CAST(N'2025-09-23T20:23:16.397' AS DateTime), 1, CAST(N'2025-09-23T20:23:16.397' AS DateTime), 1, NULL, NULL, N'User', N'{"verbal_reply":"Don\u0027t be so hard on yourself! Choosing the right data structure can be tricky. Think about how you would manually keep track of which opening parenthesis needs to be closed. Would you use a list, a stack, or something else?","scores":{"correctness":0.3,"completeness":0.2,"clarity":0.4,"alignment":0.7},"explaination_of_approach":"The user is stuck on the data structure needed to solve the problem."}', N'Don''t be so hard on yourself! Choosing the right data structure can be tricky. Think about how you would manually keep track of which opening parenthesis needs to be closed. Would you use a list, a stack, or something else?', N'The user is stuck on the data structure needed to solve the problem.', 0, 0)
