  const stack = [];
  const map = {
    '')'': ''('',
    ''}'': ''{'',
    '']'': ''[''
  };

  for (let char of s) {
    if (char === ''('' || char === ''{'' || char === ''['') {
      stack.push(char);
    } else {
      if (stack.pop() !== map[char]) {
        return false;
      }
    }
  }

  return stack.length === 0;
}

// Example usage:
console.log(isValid("()"));        // true
console.log(isValid("()[]{}"));    // true
console.log(isValid("(]"));        // false
console.log(isValid("([)]"));      // false
console.log(isValid("{[]}"));      // true
