        } else {
            if (st.empty()) return false; // No matching opening bracket
            char top = st.top();
            st.pop();
            if ((c == '')'' && top != ''('') ||
                (c == ''}'' && top != ''{'') ||
                (c == '']'' && top != ''[''))
                return false;
        }
    }
    return st.empty(); // All brackets should be matched
